// L2 chỉ cho dữ liệu tham chiếu đọc nhiều ghi ít
@Entity
@Cache(usage = CacheConcurrencyStrategy.READ_ONLY)
public class Country { @Id String code; String name; }

@Entity
public class Order {
    @ManyToOne(fetch = FetchType.LAZY)   // đặt tường minh: mặc định là EAGER
    @JoinColumn(name = "customer_id")
    private Customer customer;

    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<OrderLine> lines = new ArrayList<>();

    public void addLine(OrderLine l) {   // đồng bộ cả hai phía
        lines.add(l);
        l.setOrder(this);
    }
}

@Entity
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "order_seq")
    @SequenceGenerator(name = "order_seq", sequenceName = "order_id_seq", allocationSize = 50)
    private Long id;
}

# Bật batch insert (phải khớp với chiến lược SEQUENCE)
spring.jpa.properties:
  hibernate.jdbc.batch_size: 50
  hibernate.order_inserts: true
  hibernate.order_updates: true

spring.datasource.hikari:
  maximum-pool-size: 10
  minimum-idle: 10            # bằng max -> pool cố định, không dao động
  connection-timeout: 3000    # fail fast thay vì treo 30 giây
  max-lifetime: 1200000       # 20 phút, nhỏ hơn timeout của database
  leak-detection-threshold: 20000

